mapper.select:
SELECT u.USER_ID AS user_id, u.USERNAME AS username, u.USERCHNNAME AS userchnname, u.EMAIL AS email, u.ISEXPIRED AS is_expired, u.ISLOCKED AS is_locked, u.PASS_WRONG_COUNT AS pass_wrong_count, u.ISENABLED AS is_enabled, u.CREATE_TIME AS create_time, u.CREATE_AUTHOR AS create_author, u.UPDATE_TIME AS update_time, u.UPDATE_AUTHOR AS update_author, u.REMARK AS remark, u.PWD_UPDATE_TIME AS pwd_update_time FROM PT_USER u INNER JOIN EXT_USER_ORG uo ON u.USER_ID = uo.USER_ID WHERE uo.ORG_CODE = #{orgCode}
AND (u.USER_ID LIKE CONCAT('%', #{keyword}, '%') OR u.USERNAME LIKE CONCAT('%', #{keyword}, '%') OR u.USERCHNNAME LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY u.USER_ID ASC LIMIT #{limit} OFFSET #{offset}
